<script setup>
import {computed, ref, watch} from 'vue';
const props=defineProps({record:{type:Object,required:true}});
defineEmits(['close']);
const tab=ref('fields'),page=ref(1),pageSize=ref(10);
const report=computed(()=>props.record.report);
const passed=computed(()=>props.record.passed ?? report.value.status==='pass');
const fields=computed(()=>report.value.fields.filter(f=>f.status!=='pass'));
const rows=computed(()=>tab.value==='fields'?fields.value:report.value.differences);
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/pageSize.value)));
const visible=computed(()=>rows.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const labels={manual:'需人工判断',issue:'规则不符',not_checked:'未能检查'};
const explanations={pass:'所有已配置规则均通过，未发现固定条款差异。',needs_changes:'存在字段规则不符或固定条款差异。',needs_review:'存在转人工字段，未达到自动校验通过条件。',incomplete:'部分内容未能完整校验。'};
const date=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
watch([tab,pageSize,()=>props.record.id],()=>page.value=1);
</script>
<template>
<section class="check-report">
  <div class="report-heading"><div><h1>模板核验报告</h1><p>{{record.filename}} · {{record.template_name}} V{{record.version}}</p><p class="report-meta">校验时间：{{date(record.created_at)}} · 记录编号：{{record.id}}</p></div><div class="report-heading-actions"><RouterLink to="/validation-records" class="button">核验记录</RouterLink><button class="button" @click="$emit('close')">返回</button></div></div>
  <div class="report-banner" :class="passed?'pass':'attention'"><span>{{passed?'✓':'!'}}</span><div><h2>{{passed?'TRUE · 校验通过':'FALSE · 校验未通过'}}</h2><p>{{explanations[report.status]}} 计算结果已自动保存。</p></div></div>
  <div class="report-stats"><div><strong>{{report.counts.total}}</strong><span>校验字段</span></div><div><strong>{{report.counts.pass}}</strong><span>字段通过</span></div><div><strong>{{fields.length}}</strong><span>字段未通过</span></div><div><strong>{{report.counts.differences}}</strong><span>固定条款差异</span></div></div>
  <div class="report-card">
    <nav class="report-tabs" aria-label="核验报告分类"><button :class="{active:tab==='fields'}" @click="tab='fields'">字段未通过项 <b>{{fields.length}}</b></button><button :class="{active:tab==='differences'}" @click="tab='differences'">固定条款差异 <b>{{report.differences.length}}</b></button></nav>
    <div v-if="tab==='fields'&&rows.length" class="report-table-wrap"><table><thead><tr><th>字段</th><th>模板内容</th><th>合同内容</th><th>结果</th><th>原因</th></tr></thead><tbody><tr v-for="f in visible" :key="f.id"><td>{{f.name}}</td><td>{{f.template_value||'（空白）'}}</td><td>{{f.value===null?'未能定位':f.value||'（空白）'}}</td><td><span class="report-badge" :class="f.status">{{labels[f.status]}}</span></td><td>{{f.reason}}</td></tr></tbody></table></div>
    <div v-else-if="tab==='differences'&&rows.length" class="report-differences"><article v-for="(d,i) in visible" :key="(page-1)*pageSize+i"><h3>变化 {{(page-1)*pageSize+i+1}} · {{d.reason}}</h3><div><p><b>模板原文</b>{{d.original}}</p><p><b>上传合同</b>{{d.current}}</p></div></article></div>
    <p v-else class="report-empty">{{tab==='fields'?'没有字段未通过项':'未发现固定条款差异'}}</p>
    <nav v-if="rows.length" class="report-pagination" aria-label="报告分页"><span role="status">共 {{rows.length}} 项 · 第 {{page}} / {{pages}} 页</span><div><select v-model.number="pageSize" class="field" aria-label="报告每页条数"><option :value="10">10 项 / 页</option><option :value="20">20 项 / 页</option><option :value="50">50 项 / 页</option></select><button class="button" :disabled="page===1" @click="page--">上一页</button><button class="button" :disabled="page===pages" @click="page++">下一页</button></div></nav>
  </div>
  <div v-if="report.limitations.length" class="report-card report-scope"><h3>未能完整校验的内容</h3><p v-for="(item,i) in report.limitations" :key="i">{{item}}</p></div>
  <p class="report-scope-note">TRUE 仅表示本次模板自动规则全部通过；规则不符、转人工或校验不完整均为 FALSE。</p>
</section>
</template>
