ing:12px;flex-wrap:wrap}.report-filters select{width:100%}.report-tabs{gap:18px;padding:0 12px}.report-tabs button{font-size:12px}.report-pagination>div{flex-wrap:wrap}table{min-width:680px}.report-differences article>div,.report-footer{flex-wrap:wrap}}

.value-caption{display:block;font-size:10px;color:#94a3b8;margin:2px 0}.report-scope-note{font-size:11px;color:#94a3b8;line-height:1.8;margin-bottom:20px}@media(max-width:700px){.report-stats{grid-template-columns:repeat(2,1fr)}}
